import { BookOpen, Building2, CheckCircle2, CircleDollarSign, FlaskConical, Library, Megaphone, PanelsTopLeft, Plus, ShieldCheck, UsersRound, X } from "lucide-react";
import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import { ApiError, apiRequest } from "../api/client";
import { EmptyPanel, ErrorPanel, LoadingPanel } from "../components/StatePanel";
import { useAuth } from "../context/AuthContext";
import { MessageKey, useI18n } from "../context/I18nContext";
import { Offering, Paginated, StudentSummary, TeacherSummary } from "../types";

type Tab = "overview" | "learning" | "announcements" | "finance" | "research" | "library" | "services" | "operations";
type Announcement = { id: number; title: string; body: string; publish_at: string; is_pinned: boolean; published_by_name: string };
type Material = { id: number; title: string; description: string; kind: string; subject_name: string; group_code: string; language: string; resource_url: string; file_name: string; published_at: string };
type Assignment = { id: number; title: string; instructions: string; subject_name: string; group_code: string; due_at: string; max_score: string };
type Submission = { id: number; assignment: number; assignment_title: string; student_name: string; text: string; status: string; score: string | null; feedback: string; submitted_at: string | null };
type Quiz = { id: number; title: string; subject_name: string; question_count: number; public_questions: Array<{ prompt: string; choices: string[] }> };
type Contract = { id: number; number: string; student_name: string; student_code: string; total_amount: string; paid_amount: string; balance: string; currency: string; status: string; schedule: Array<{ id: number; due_date: string; amount: string }>; payments: Array<{ id: number; payment_date: string; amount: string; reference: string }> };
type Research = { id: number; student: number; supervisor: number; title: string; student_name: string; supervisor_name: string; project_type: string; status: string; defence_date: string | null; milestones: Array<{ id: number; title: string; due_date: string; completed_at: string | null; feedback: string }> };
type Book = { id: number; title: string; authors: string; isbn: string; publication_year: number | null; available_copies: number; total_copies: number; resource_url: string };
type Service = { id: number; code: string; title: string; description: string; contact: string };
type Staff = { id: number; employee_id: string; full_name: string; department: string; position: string; status: string };
type Risk = { id: number; student_name: string; student_code: string; category: string; severity: string; status: string; reason: string; notes: Array<{ id: number; text: string; author_name: string; created_at: string }> };
type Integration = { id: number; kind: string; kind_label: string; status: string; provider_name: string; public_note: string };
type Message = { id: number; sender: number; sender_name: string; recipient: number; recipient_name: string; subject: string; body: string; sent_at: string; read_at: string | null };
type HRDocument = { id: number; employee: number; employee_name: string; document_type: string; title: string; number: string };
type HROrder = { id: number; employee: number; employee_name: string; number: string; order_type: string; order_date: string; summary: string };
type LibraryLoan = { id: number; item: number; item_title: string; student: number; student_name: string; borrowed_at: string; due_at: string; returned_at: string | null };

export function CampusPage() {
  const { user } = useAuth();
  const { t, language } = useI18n();
  const [tab, setTab] = useState<Tab>("overview");
  const [overview, setOverview] = useState<Record<string, string | number>>({});
  const [announcements, setAnnouncements] = useState<Announcement[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [assignments, setAssignments] = useState<Assignment[]>([]);
  const [submissions, setSubmissions] = useState<Submission[]>([]);
  const [quizzes, setQuizzes] = useState<Quiz[]>([]);
  const [contracts, setContracts] = useState<Contract[]>([]);
  const [research, setResearch] = useState<Research[]>([]);
  const [books, setBooks] = useState<Book[]>([]);
  const [services, setServices] = useState<Service[]>([]);
  const [staff, setStaff] = useState<Staff[]>([]);
  const [risks, setRisks] = useState<Risk[]>([]);
  const [integrations, setIntegrations] = useState<Integration[]>([]);
  const [students, setStudents] = useState<StudentSummary[]>([]);
  const [teachers, setTeachers] = useState<TeacherSummary[]>([]);
  const [messages, setMessages] = useState<Message[]>([]);
  const [hrDocuments, setHrDocuments] = useState<HRDocument[]>([]);
  const [hrOrders, setHrOrders] = useState<HROrder[]>([]);
  const [loans, setLoans] = useState<LibraryLoan[]>([]);
  const [offerings, setOfferings] = useState<Offering[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [learningForm, setLearningForm] = useState<"material" | "assignment" | "quiz" | null>(null);
  const [materialForm, setMaterialForm] = useState({ offering: "", title: "", description: "", kind: "lecture", language, resource_url: "" });
  const [assignmentForm, setAssignmentForm] = useState({ offering: "", title: "", instructions: "", due_at: "", max_score: "100" });
  const [quizForm, setQuizForm] = useState({ offering: "", title: "", questions: [{ prompt: "", choices: ["", ""], correct_index: 0 }] });
  const [submissionText, setSubmissionText] = useState<Record<number, string>>({});
  const [financeForm, setFinanceForm] = useState<"contract" | "payment" | null>(null);
  const [contractForm, setContractForm] = useState({ student: "", number: "", total_amount: "", currency: "TJS", signed_date: "", due_date: "", due_amount: "" });
  const [paymentForm, setPaymentForm] = useState({ contract: "", payment_date: "", amount: "", reference: "", note: "" });
  const [grading, setGrading] = useState<Record<number, { score: string; feedback: string }>>({});
  const [activeQuiz, setActiveQuiz] = useState<Quiz | null>(null);
  const [quizAnswers, setQuizAnswers] = useState<number[]>([]);
  const [quizResult, setQuizResult] = useState<{ correct_count: number; total_count: number } | null>(null);
  const [operationsForm, setOperationsForm] = useState<"employee" | "risk" | "note" | "document" | "order" | null>(null);
  const [employeeForm, setEmployeeForm] = useState({ employee_id: "", full_name: "", department: "", position: "", hire_date: "", status: "active" });
  const [riskForm, setRiskForm] = useState({ student: "", category: "attendance", severity: "medium", reason: "" });
  const [showMessage, setShowMessage] = useState(false);
  const [messageForm, setMessageForm] = useState({ recipient: "", subject: "", body: "" });
  const [selectedRisk, setSelectedRisk] = useState<Risk | null>(null);
  const [riskNote, setRiskNote] = useState("");
  const [documentForm, setDocumentForm] = useState({ employee: "", document_type: "contract", title: "", number: "", issue_date: "", expiry_date: "" });
  const [orderForm, setOrderForm] = useState({ employee: "", number: "", order_type: "appointment", order_date: "", summary: "" });
  const [researchForm, setResearchForm] = useState<"project" | "milestone" | null>(null);
  const [projectForm, setProjectForm] = useState({ student: "", supervisor: "", project_type: "coursework", title: "", status: "proposed", defence_date: "" });
  const [milestoneForm, setMilestoneForm] = useState({ project: "", title: "", due_date: "", feedback: "" });
  const [libraryForm, setLibraryForm] = useState<"item" | "loan" | null>(null);
  const [bookForm, setBookForm] = useState({ title: "", authors: "", isbn: "", publication_year: "", total_copies: "1", resource_url: "" });
  const [loanForm, setLoanForm] = useState({ item: "", student: "", borrowed_at: "", due_at: "" });

  const load = useCallback(async () => {
    if (!user) return; setLoading(true); setError("");
    try {
      const base = await Promise.all([
        apiRequest<Record<string, string | number>>("/campus-overview/"),
        apiRequest<Paginated<Announcement>>(`/announcements/?page_size=100&lang=${language}`),
        apiRequest<Paginated<Material>>(`/learning-materials/?page_size=100&lang=${language}`),
        apiRequest<Paginated<Assignment>>(`/assignments/?page_size=100&lang=${language}`),
        apiRequest<Paginated<Research>>(`/research-projects/?page_size=100`),
        apiRequest<Paginated<Book>>(`/library-items/?page_size=100`),
        apiRequest<Paginated<Service>>(`/student-services/?is_active=true&page_size=100&lang=${language}`),
        apiRequest<Paginated<Submission>>("/assignment-submissions/?page_size=100"),
        apiRequest<Paginated<Quiz>>("/self-check-quizzes/?is_published=true&page_size=100"),
        apiRequest<Paginated<Message>>("/messages/?page_size=100"),
        apiRequest<Paginated<StudentSummary>>("/students/?status=active&page_size=100"),
        apiRequest<Paginated<TeacherSummary>>("/teachers/?page_size=100"),
        apiRequest<Paginated<LibraryLoan>>("/library-loans/?page_size=100"),
      ]);
      setOverview(base[0]); setAnnouncements(base[1].results); setMaterials(base[2].results); setAssignments(base[3].results); setResearch(base[4].results); setBooks(base[5].results); setServices(base[6].results); setSubmissions(base[7].results); setQuizzes(base[8].results); setMessages(base[9].results); setStudents(base[10].results); setTeachers(base[11].results); setLoans(base[12].results);
      if (user.role !== "teacher") setContracts((await apiRequest<Paginated<Contract>>("/student-contracts/?page_size=100")).results);
      if (user.role !== "student") setOfferings((await apiRequest<Paginated<Offering>>(`/offerings/?is_active=true&page_size=100&lang=${language}`)).results);
      if (user.role === "admin") {
        const [staffData, riskData, integrationData, documentData, orderData] = await Promise.all([
          apiRequest<Paginated<Staff>>("/staff-employees/?page_size=100"), apiRequest<Paginated<Risk>>("/risk-cases/?page_size=100"), apiRequest<Paginated<Integration>>("/integration-endpoints/?page_size=100"), apiRequest<Paginated<HRDocument>>("/hr-documents/?page_size=100"), apiRequest<Paginated<HROrder>>("/hr-orders/?page_size=100"),
        ]);
        setStaff(staffData.results); setRisks(riskData.results); setIntegrations(integrationData.results); setHrDocuments(documentData.results); setHrOrders(orderData.results);
      }
    } catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); }
    finally { setLoading(false); }
  }, [user, language, t]);
  useEffect(() => { void load(); }, [load]);

  const tabs = useMemo<Array<{ id: Tab; label: string; icon: typeof PanelsTopLeft }>>(() => [
    { id: "overview", label: t("campus.overview"), icon: PanelsTopLeft },
    { id: "learning", label: t("campus.learning"), icon: BookOpen },
    { id: "announcements", label: t("campus.announcements"), icon: Megaphone },
    ...(user?.role !== "teacher" ? [{ id: "finance" as Tab, label: t("campus.finance"), icon: CircleDollarSign }] : []),
    { id: "research", label: t("campus.research"), icon: FlaskConical },
    { id: "library", label: t("campus.library"), icon: Library },
    { id: "services", label: t("campus.services"), icon: Building2 },
    ...(user?.role === "admin" ? [{ id: "operations" as Tab, label: t("campus.operations"), icon: UsersRound }] : []),
  ], [user, t]);
  const recipients = useMemo(() => {
    const options = [...teachers.map((item) => ({ id: item.user.id, name: item.user.display_name, detail: item.employee_id })), ...students.map((item) => ({ id: item.user.id, name: item.user.display_name, detail: item.student_id }))];
    return [...new Map(options.filter((item) => item.id !== user?.id).map((item) => [item.id, item])).values()];
  }, [teachers, students, user?.id]);

  const localizedOffering = (offering: Offering) => language === "tj" ? offering.subject_name_tj : language === "en" ? offering.subject_name_en : offering.subject_name;
  const overviewLabel = (key: string) => t(`campus.metric.${key}` as MessageKey);
  const createMaterial = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/learning-materials/", { method: "POST", body: JSON.stringify({ ...materialForm, offering: Number(materialForm.offering), is_published: true }) }); setLearningForm(null); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const createAssignment = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/assignments/", { method: "POST", body: JSON.stringify({ ...assignmentForm, offering: Number(assignmentForm.offering), is_published: true }) }); setLearningForm(null); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const submitAssignment = async (assignment: Assignment) => {
    setBusy(true); setError("");
    try { const existing = submissions.find((item) => item.assignment === assignment.id); await apiRequest(existing ? `/assignment-submissions/${existing.id}/` : "/assignment-submissions/", { method: existing ? "PATCH" : "POST", body: JSON.stringify({ assignment: assignment.id, text: submissionText[assignment.id] || "", status: "submitted", file_name: "" }) }); setSubmissionText({ ...submissionText, [assignment.id]: "" }); await load(); }
    catch (caught) { setError(caught instanceof ApiError ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const createQuiz = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/self-check-quizzes/", { method: "POST", body: JSON.stringify({ offering: Number(quizForm.offering), title: quizForm.title, questions: quizForm.questions, is_published: true }) }); setLearningForm(null); setQuizForm({ offering: "", title: "", questions: [{ prompt: "", choices: ["", ""], correct_index: 0 }] }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const gradeSubmission = async (submission: Submission) => {
    const values = grading[submission.id] || { score: submission.score || "", feedback: submission.feedback || "" };
    setBusy(true); setError("");
    try { await apiRequest(`/assignment-submissions/${submission.id}/`, { method: "PATCH", body: JSON.stringify({ score: values.score, feedback: values.feedback, status: "graded" }) }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const openQuiz = (quiz: Quiz) => { setActiveQuiz(quiz); setQuizAnswers(Array(quiz.question_count).fill(-1)); setQuizResult(null); };
  const submitQuiz = async () => {
    if (!activeQuiz) return; setBusy(true); setError("");
    try { setQuizResult(await apiRequest<{ correct_count: number; total_count: number }>(`/self-check-quizzes/${activeQuiz.id}/submit/`, { method: "POST", body: JSON.stringify({ answers: quizAnswers }) })); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const createContract = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try {
      const contract = await apiRequest<Contract>("/student-contracts/", { method: "POST", body: JSON.stringify({ student: Number(contractForm.student), number: contractForm.number, total_amount: contractForm.total_amount, currency: contractForm.currency, signed_date: contractForm.signed_date, status: "active" }) });
      if (contractForm.due_date && contractForm.due_amount) await apiRequest("/payment-schedule/", { method: "POST", body: JSON.stringify({ contract: contract.id, due_date: contractForm.due_date, amount: contractForm.due_amount, note: "" }) });
      setFinanceForm(null); setContractForm({ student: "", number: "", total_amount: "", currency: "TJS", signed_date: "", due_date: "", due_amount: "" }); await load();
    } catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const confirmPayment = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/confirmed-payments/", { method: "POST", body: JSON.stringify({ ...paymentForm, contract: Number(paymentForm.contract), is_confirmed: true }) }); setFinanceForm(null); setPaymentForm({ contract: "", payment_date: "", amount: "", reference: "", note: "" }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const createEmployee = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/staff-employees/", { method: "POST", body: JSON.stringify({ ...employeeForm, faculty: null, user: null }) }); setOperationsForm(null); setEmployeeForm({ employee_id: "", full_name: "", department: "", position: "", hire_date: "", status: "active" }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const createRisk = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/risk-cases/", { method: "POST", body: JSON.stringify({ ...riskForm, student: Number(riskForm.student), status: "open", assigned_to: null }) }); setOperationsForm(null); setRiskForm({ student: "", category: "attendance", severity: "medium", reason: "" }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const resolveRisk = async (risk: Risk) => {
    setBusy(true); setError("");
    try { await apiRequest(`/risk-cases/${risk.id}/`, { method: "PATCH", body: JSON.stringify({ status: "resolved" }) }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const addRiskNote = async (event: FormEvent) => {
    event.preventDefault(); if (!selectedRisk) return; setBusy(true); setError("");
    try { await apiRequest("/risk-case-notes/", { method: "POST", body: JSON.stringify({ case: selectedRisk.id, text: riskNote }) }); setOperationsForm(null); setSelectedRisk(null); setRiskNote(""); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const createHRDocument = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/hr-documents/", { method: "POST", body: JSON.stringify({ ...documentForm, employee: Number(documentForm.employee), issue_date: documentForm.issue_date || null, expiry_date: documentForm.expiry_date || null, file_name: "" }) }); setOperationsForm(null); setDocumentForm({ employee: "", document_type: "contract", title: "", number: "", issue_date: "", expiry_date: "" }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const createHROrder = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/hr-orders/", { method: "POST", body: JSON.stringify({ ...orderForm, employee: Number(orderForm.employee) }) }); setOperationsForm(null); setOrderForm({ employee: "", number: "", order_type: "appointment", order_date: "", summary: "" }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const createProject = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/research-projects/", { method: "POST", body: JSON.stringify({ ...projectForm, student: Number(projectForm.student), supervisor: Number(projectForm.supervisor), defence_date: projectForm.defence_date || null }) }); setResearchForm(null); setProjectForm({ student: "", supervisor: "", project_type: "coursework", title: "", status: "proposed", defence_date: "" }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const createMilestone = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/research-milestones/", { method: "POST", body: JSON.stringify({ ...milestoneForm, project: Number(milestoneForm.project), completed_at: null }) }); setResearchForm(null); setMilestoneForm({ project: "", title: "", due_date: "", feedback: "" }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const createLibraryItem = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/library-items/", { method: "POST", body: JSON.stringify({ ...bookForm, publication_year: bookForm.publication_year ? Number(bookForm.publication_year) : null, total_copies: Number(bookForm.total_copies), available_copies: Number(bookForm.total_copies) }) }); setLibraryForm(null); setBookForm({ title: "", authors: "", isbn: "", publication_year: "", total_copies: "1", resource_url: "" }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const createLibraryLoan = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/library-loans/", { method: "POST", body: JSON.stringify({ ...loanForm, item: Number(loanForm.item), student: Number(loanForm.student), returned_at: null }) }); setLibraryForm(null); setLoanForm({ item: "", student: "", borrowed_at: "", due_at: "" }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const returnLibraryLoan = async (loan: LibraryLoan) => {
    setBusy(true); setError("");
    try { await apiRequest(`/library-loans/${loan.id}/`, { method: "PATCH", body: JSON.stringify({ returned_at: new Date().toISOString().slice(0, 10) }) }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const sendMessage = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError("");
    try { await apiRequest("/messages/", { method: "POST", body: JSON.stringify({ ...messageForm, recipient: Number(messageForm.recipient) }) }); setShowMessage(false); setMessageForm({ recipient: "", subject: "", body: "" }); await load(); }
    catch (caught) { setError(caught instanceof Error ? caught.message : t("common.error")); } finally { setBusy(false); }
  };
  const readMessage = async (message: Message) => {
    if (message.recipient !== user?.id || message.read_at) return;
    try { await apiRequest(`/messages/${message.id}/mark-read/`, { method: "POST", body: JSON.stringify({}) }); setMessages((current) => current.map((item) => item.id === message.id ? { ...item, read_at: new Date().toISOString() } : item)); }
    catch { setError(t("common.error")); }
  };

  if (!user) return null;
  if (loading) return <LoadingPanel />;
  if (error && !Object.keys(overview).length) return <ErrorPanel onRetry={load} message={error} />;
  return (
    <div className="page">
      <header className="page-heading"><span className="eyebrow">{t("campus.eyebrow")}</span><h1>{t("campus.title")}</h1><p>{t("campus.subtitle")}</p></header>
      {error && <div className="inline-notice inline-notice--error">{error}<button type="button" onClick={() => setError("")}><X size={15} /></button></div>}
      <nav className="module-tabs" aria-label={t("campus.title")}>{tabs.map(({ id, label, icon: Icon }) => <button key={id} type="button" className={tab === id ? "is-active" : ""} onClick={() => setTab(id)}><Icon size={16} />{label}</button>)}</nav>

      {tab === "overview" && <section className="campus-overview">{Object.entries(overview).map(([key, value], index) => <article className={`campus-metric campus-metric--${(index % 4) + 1} surface`} key={key}><span>{String(index + 1).padStart(2, "0")}</span><strong>{value}</strong><small>{overviewLabel(key)}</small></article>)}</section>}

      {tab === "learning" && <section className="campus-stack">
        <div className="section-heading section-heading--actions"><div><span className="eyebrow">{t("campus.learning")}</span><h2>{t("campus.materials")}</h2></div>{user.role !== "student" && <button className="button button--secondary button--small" type="button" onClick={() => setLearningForm("material")}><Plus size={15} />{t("campus.newMaterial")}</button>}</div>
        {materials.length ? <div className="resource-grid">{materials.map((item) => <article className="resource-card surface" key={item.id}><span className="code-badge">{item.kind}</span><h3>{item.title}</h3><p>{item.description || item.subject_name}</p><small>{item.group_code} · {item.language.toUpperCase()}</small>{item.resource_url && <a href={item.resource_url} target="_blank" rel="noreferrer">{item.resource_url}</a>}</article>)}</div> : <EmptyPanel>{t("campus.empty")}</EmptyPanel>}
        <div className="section-heading section-heading--actions"><div><span className="eyebrow">{t("campus.learning")}</span><h2>{t("campus.assignments")}</h2></div>{user.role !== "student" && <button className="button button--secondary button--small" type="button" onClick={() => setLearningForm("assignment")}><Plus size={15} />{t("campus.newAssignment")}</button>}</div>
        {assignments.length ? <div className="resource-grid">{assignments.map((item) => { const existing = submissions.find((entry) => entry.assignment === item.id); return <article className="resource-card surface" key={item.id}><span className="workflow-status workflow-status--submitted">{item.group_code}</span><h3>{item.title}</h3><p>{item.instructions}</p><small>{t("campus.deadline")}: {new Date(item.due_at).toLocaleString(language === "tj" ? "tg-TJ" : language)}</small>{user.role === "student" && <div className="submission-box">{existing && <span className={`workflow-status workflow-status--${existing.status}`}>{t(`submission.${existing.status}` as "submission.submitted")}{existing.score !== null ? ` · ${existing.score}/${item.max_score}` : ""}</span>} {existing?.feedback && <p>{existing.feedback}</p>}<textarea value={submissionText[item.id] ?? existing?.text ?? ""} onChange={(event) => setSubmissionText({ ...submissionText, [item.id]: event.target.value })} /><button className="button button--primary button--small" type="button" disabled={busy || !(submissionText[item.id] ?? existing?.text)?.trim() || existing?.status === "graded"} onClick={() => void submitAssignment(item)}>{existing ? t("campus.resubmit") : t("campus.submit")}</button></div>}</article>; })}</div> : <EmptyPanel>{t("campus.empty")}</EmptyPanel>}
        <div className="section-heading section-heading--actions"><div><span className="eyebrow">{t("campus.learning")}</span><h2>{t("campus.selfChecks")}</h2></div>{user.role !== "student" && <button className="button button--secondary button--small" type="button" onClick={() => setLearningForm("quiz")}><Plus size={15} />{t("campus.newQuiz")}</button>}</div>
        {quizzes.length ? <div className="resource-grid">{quizzes.map((quiz) => <article className="quiz-card surface" key={quiz.id}><span>{quiz.question_count}</span><h3>{quiz.title}</h3><p>{quiz.subject_name}</p>{user.role === "student" && <button className="button button--secondary button--small" type="button" onClick={() => openQuiz(quiz)}>{t("campus.startQuiz")}</button>}</article>)}</div> : <EmptyPanel>{t("campus.empty")}</EmptyPanel>}
        {user.role === "teacher" && <><div className="section-heading"><div><span className="eyebrow">{t("campus.assignments")}</span><h2>{t("campus.reviewSubmissions")}</h2></div><span className="count-pill">{submissions.filter((item) => item.status === "submitted").length}</span></div>{submissions.length ? <div className="submission-review">{submissions.map((item) => { const values = grading[item.id] || { score: item.score || "", feedback: item.feedback || "" }; return <article className="surface" key={item.id}><header><div><strong>{item.student_name}</strong><small>{item.assignment_title}</small></div><span className={`workflow-status workflow-status--${item.status}`}>{t(`submission.${item.status}` as "submission.submitted")}</span></header><p>{item.text || "—"}</p><div><label className="field"><span>{t("exams.score")}</span><input type="number" min="0" value={values.score} onChange={(event) => setGrading({ ...grading, [item.id]: { ...values, score: event.target.value } })} /></label><label className="field"><span>{t("exams.comment")}</span><input value={values.feedback} onChange={(event) => setGrading({ ...grading, [item.id]: { ...values, feedback: event.target.value } })} /></label><button className="button button--primary button--small" type="button" disabled={busy || !values.score} onClick={() => void gradeSubmission(item)}>{t("campus.gradeWork")}</button></div></article>; })}</div> : <EmptyPanel>{t("campus.noSubmissions")}</EmptyPanel>}</>}
      </section>}

      {tab === "announcements" && <section className="campus-stack"><div className="section-heading"><div><span className="eyebrow">{t("campus.announcements")}</span><h2>{t("communication.news")}</h2></div></div><div className="announcement-list">{announcements.length ? announcements.map((item) => <article className="announcement-card surface" key={item.id}><Megaphone /><div><span>{new Date(item.publish_at).toLocaleDateString(language === "tj" ? "tg-TJ" : language)} · {item.published_by_name}</span><h2>{item.title}</h2><p>{item.body}</p></div></article>) : <EmptyPanel>{t("campus.empty")}</EmptyPanel>}</div><div className="section-heading section-heading--actions"><div><span className="eyebrow">{t("communication.private")}</span><h2>{t("communication.messages")}</h2></div><button className="button button--primary button--small" type="button" disabled={!recipients.length} onClick={() => setShowMessage(true)}><Plus size={15} />{t("communication.compose")}</button></div>{messages.length ? <div className="message-list">{messages.map((item) => <button type="button" className={`message-card surface ${!item.read_at && item.recipient === user.id ? "is-unread" : ""}`} key={item.id} onClick={() => void readMessage(item)}><span className="avatar">{(item.sender === user.id ? item.recipient_name : item.sender_name).slice(0, 2)}</span><div><small>{item.sender === user.id ? `${t("communication.to")}: ${item.recipient_name}` : `${t("communication.from")}: ${item.sender_name}`}</small><strong>{item.subject}</strong><p>{item.body}</p></div><time>{new Date(item.sent_at).toLocaleDateString(language === "tj" ? "tg-TJ" : language)}</time></button>)}</div> : <EmptyPanel>{t("communication.empty")}</EmptyPanel>}</section>}

      {tab === "finance" && <section className="campus-stack">{user.role === "admin" && <div className="section-heading section-heading--actions"><div><span className="eyebrow">{t("campus.finance")}</span><h2>{t("campus.contracts")}</h2></div><div className="page-heading__actions"><button className="button button--secondary button--small" type="button" onClick={() => setFinanceForm("payment")}><CircleDollarSign size={15} />{t("finance.confirmPayment")}</button><button className="button button--primary button--small" type="button" onClick={() => setFinanceForm("contract")}><Plus size={15} />{t("finance.newContract")}</button></div></div>}<div className="resource-grid">{contracts.length ? contracts.map((item) => <article className="finance-card surface" key={item.id}><header><span>{item.number}</span><span className="workflow-status workflow-status--accepted">{item.status}</span></header><h3>{user.role === "admin" ? item.student_name : t("campus.contracts")}</h3><div><span><small>{t("campus.total")}</small><strong>{item.total_amount} {item.currency}</strong></span><span><small>{t("campus.paid")}</small><strong>{item.paid_amount} {item.currency}</strong></span><span><small>{t("campus.balance")}</small><strong>{item.balance} {item.currency}</strong></span></div>{item.schedule?.[0] && <footer>{t("finance.nextDue")}: {item.schedule[0].due_date} · {item.schedule[0].amount} {item.currency}</footer>}</article>) : <EmptyPanel>{t("campus.empty")}</EmptyPanel>}</div></section>}

      {tab === "research" && <section className="campus-stack"><div className="section-heading section-heading--actions"><div><span className="eyebrow">{t("campus.research")}</span><h2>{t("research.projects")}</h2></div>{user.role !== "student" && <div className="page-heading__actions"><button className="button button--secondary button--small" type="button" disabled={!research.length} onClick={() => setResearchForm("milestone")}><Plus size={15} />{t("research.newMilestone")}</button><button className="button button--primary button--small" type="button" onClick={() => setResearchForm("project")}><Plus size={15} />{t("research.newProject")}</button></div>}</div><div className="resource-grid">{research.length ? research.map((item) => <article className="resource-card surface" key={item.id}><span className="workflow-status workflow-status--under_review">{item.project_type}</span><h3>{item.title}</h3><p>{item.student_name}</p><small>{t("campus.supervisor")}: {item.supervisor_name}</small>{item.milestones?.[0] && <div className="milestone-preview"><span>{item.milestones.filter((milestone) => milestone.completed_at).length}/{item.milestones.length}</span><p>{item.milestones[0].title} · {item.milestones[0].due_date}</p></div>}</article>) : <EmptyPanel>{t("campus.empty")}</EmptyPanel>}</div></section>}

      {tab === "library" && <section className="campus-stack">{user.role === "admin" && <div className="section-heading section-heading--actions"><div><span className="eyebrow">{t("campus.library")}</span><h2>{t("library.catalogue")}</h2></div><div className="page-heading__actions"><button className="button button--secondary button--small" type="button" onClick={() => setLibraryForm("loan")}><BookOpen size={15} />{t("library.newLoan")}</button><button className="button button--primary button--small" type="button" onClick={() => setLibraryForm("item")}><Plus size={15} />{t("library.newItem")}</button></div></div>}<div className="resource-grid">{books.length ? books.map((item) => <article className="book-card surface" key={item.id}><span><Library /></span><h3>{item.title}</h3><p>{item.authors}</p><small>{t("campus.available")}: {item.available_copies}/{item.total_copies}</small>{item.isbn && <code>{item.isbn}</code>}</article>) : <EmptyPanel>{t("campus.empty")}</EmptyPanel>}</div>{loans.length > 0 && <><div className="section-heading"><div><span className="eyebrow">{t("campus.library")}</span><h2>{user.role === "student" ? t("library.myLoans") : t("library.activeLoans")}</h2></div><span className="count-pill">{loans.filter((item) => !item.returned_at).length}</span></div><div className="loan-list">{loans.map((loan) => <article className={`surface ${loan.returned_at ? "is-returned" : ""}`} key={loan.id}><Library /><div><strong>{loan.item_title}</strong><small>{user.role === "admin" ? `${loan.student_name} · ` : ""}{loan.borrowed_at} — {loan.due_at}</small></div>{loan.returned_at ? <span>{t("library.returned")}</span> : user.role === "admin" ? <button className="button button--secondary button--small" type="button" disabled={busy} onClick={() => void returnLibraryLoan(loan)}>{t("library.return")}</button> : <span className="workflow-status workflow-status--submitted">{t("library.onLoan")}</span>}</article>)}</div></>}</section>}

      {tab === "services" && <section className="resource-grid">{services.length ? services.map((item) => <article className="service-card surface" key={item.id}><span>{item.code}</span><h3>{item.title}</h3><p>{item.description}</p><small>{t("campus.contact")}: {item.contact}</small></article>) : <EmptyPanel>{t("campus.empty")}</EmptyPanel>}</section>}

      {tab === "operations" && <section className="operations-grid"><div className="surface operations-panel"><div className="operations-heading"><h2>{t("campus.staff")} <span className="count-pill">{staff.length}</span></h2><div><button className="icon-button" type="button" onClick={() => setOperationsForm("document")} aria-label={t("operations.newDocument")}><BookOpen /></button><button className="icon-button" type="button" onClick={() => setOperationsForm("order")} aria-label={t("operations.newOrder")}><FlaskConical /></button><button className="icon-button" type="button" onClick={() => setOperationsForm("employee")} aria-label={t("operations.newEmployee")}><Plus /></button></div></div>{staff.slice(0, 8).map((item) => <div className="operation-row" key={item.id}><span className="avatar">{item.full_name.slice(0, 2)}</span><div><strong>{item.full_name}</strong><small>{item.position} · {item.department}</small></div><span>{item.employee_id}</span></div>)}<div className="hr-summary"><span>{t("operations.documents")} <strong>{hrDocuments.length}</strong></span><span>{t("operations.orders")} <strong>{hrOrders.length}</strong></span></div></div><div className="surface operations-panel"><div className="operations-heading"><h2>{t("campus.risks")} <span className="count-pill">{risks.length}</span></h2><button className="icon-button" type="button" onClick={() => setOperationsForm("risk")} aria-label={t("operations.newRisk")}><Plus /></button></div>{risks.slice(0, 8).map((item) => <div className="operation-row operation-row--risk" key={item.id}><span className={`risk-dot risk-dot--${item.severity}`} /><div><strong>{item.student_name}</strong><small>{item.category} · {item.reason}{item.notes?.length ? ` · ${item.notes.length} ${t("operations.notes")}` : ""}</small></div><div className="operation-row__actions"><button className="button button--secondary button--small" type="button" onClick={() => { setSelectedRisk(item); setOperationsForm("note"); }}>{t("operations.addNote")}</button>{item.status === "resolved" ? <span>{t("risk.resolved")}</span> : <button className="button button--secondary button--small" type="button" disabled={busy} onClick={() => void resolveRisk(item)}>{t("operations.resolve")}</button>}</div></div>)}</div><div className="surface operations-panel operations-panel--wide"><h2>{t("campus.integrations")} <span className="count-pill">{integrations.length}</span></h2><div className="integration-grid">{integrations.map((item) => <article key={item.id}><ShieldCheck /><div><strong>{item.kind_label}</strong><small>{item.public_note || t("campus.external")}</small></div><span className={`workflow-status workflow-status--${item.status}`}>{t(`integration.${item.status}` as "integration.config_required")}</span></article>)}</div></div></section>}

      {learningForm === "material" && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={createMaterial}><header><h2>{t("campus.newMaterial")}</h2><button className="icon-button" type="button" onClick={() => setLearningForm(null)}><X /></button></header><label className="field"><span>{t("schedule.course")}</span><select required value={materialForm.offering} onChange={(event) => setMaterialForm({ ...materialForm, offering: event.target.value })}><option value="" />{offerings.map((item) => <option key={item.id} value={item.id}>{localizedOffering(item)} · {item.group_code}</option>)}</select></label><label className="field"><span>{t("campus.fieldTitle")}</span><input required value={materialForm.title} onChange={(event) => setMaterialForm({ ...materialForm, title: event.target.value })} /></label><label className="field"><span>{t("campus.description")}</span><input value={materialForm.description} onChange={(event) => setMaterialForm({ ...materialForm, description: event.target.value })} /></label><label className="field"><span>{t("campus.resourceUrl")}</span><input type="url" value={materialForm.resource_url} onChange={(event) => setMaterialForm({ ...materialForm, resource_url: event.target.value })} /></label><footer><button className="button button--secondary" type="button" onClick={() => setLearningForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
      {learningForm === "assignment" && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={createAssignment}><header><h2>{t("campus.newAssignment")}</h2><button className="icon-button" type="button" onClick={() => setLearningForm(null)}><X /></button></header><label className="field"><span>{t("schedule.course")}</span><select required value={assignmentForm.offering} onChange={(event) => setAssignmentForm({ ...assignmentForm, offering: event.target.value })}><option value="" />{offerings.map((item) => <option key={item.id} value={item.id}>{localizedOffering(item)} · {item.group_code}</option>)}</select></label><label className="field"><span>{t("campus.fieldTitle")}</span><input required value={assignmentForm.title} onChange={(event) => setAssignmentForm({ ...assignmentForm, title: event.target.value })} /></label><label className="field"><span>{t("campus.instructions")}</span><textarea required value={assignmentForm.instructions} onChange={(event) => setAssignmentForm({ ...assignmentForm, instructions: event.target.value })} /></label><label className="field"><span>{t("campus.deadline")}</span><input type="datetime-local" required value={assignmentForm.due_at} onChange={(event) => setAssignmentForm({ ...assignmentForm, due_at: event.target.value })} /></label><label className="field"><span>{t("exams.maxScore")}</span><input required value={assignmentForm.max_score} onChange={(event) => setAssignmentForm({ ...assignmentForm, max_score: event.target.value })} /></label><footer><button className="button button--secondary" type="button" onClick={() => setLearningForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
      {learningForm === "quiz" && <div className="dialog-backdrop"><form className="dialog surface" onSubmit={createQuiz}><header><h2>{t("campus.newQuiz")}</h2><button className="icon-button" type="button" onClick={() => setLearningForm(null)}><X /></button></header><div className="form-grid"><label className="field"><span>{t("schedule.course")}</span><select required value={quizForm.offering} onChange={(event) => setQuizForm({ ...quizForm, offering: event.target.value })}><option value="" />{offerings.map((item) => <option key={item.id} value={item.id}>{localizedOffering(item)} · {item.group_code}</option>)}</select></label><label className="field"><span>{t("campus.fieldTitle")}</span><input required value={quizForm.title} onChange={(event) => setQuizForm({ ...quizForm, title: event.target.value })} /></label></div><div className="quiz-builder">{quizForm.questions.map((question, questionIndex) => <fieldset key={questionIndex}><legend>{t("campus.question")} {questionIndex + 1}</legend><label className="field"><span>{t("campus.questionText")}</span><input required value={question.prompt} onChange={(event) => setQuizForm({ ...quizForm, questions: quizForm.questions.map((item, index) => index === questionIndex ? { ...item, prompt: event.target.value } : item) })} /></label>{question.choices.map((choice, choiceIndex) => <label className="field" key={choiceIndex}><span>{t("campus.option")} {choiceIndex + 1}</span><input required value={choice} onChange={(event) => setQuizForm({ ...quizForm, questions: quizForm.questions.map((item, index) => index === questionIndex ? { ...item, choices: item.choices.map((value, optionIndex) => optionIndex === choiceIndex ? event.target.value : value) } : item) })} /></label>)}<label className="field"><span>{t("campus.correctAnswer")}</span><select value={question.correct_index} onChange={(event) => setQuizForm({ ...quizForm, questions: quizForm.questions.map((item, index) => index === questionIndex ? { ...item, correct_index: Number(event.target.value) } : item) })}>{question.choices.map((_choice, index) => <option value={index} key={index}>{index + 1}</option>)}</select></label></fieldset>)}</div><button className="button button--secondary button--small" type="button" onClick={() => setQuizForm({ ...quizForm, questions: [...quizForm.questions, { prompt: "", choices: ["", ""], correct_index: 0 }] })}><Plus size={15} />{t("campus.addQuestion")}</button><footer><button className="button button--secondary" type="button" onClick={() => setLearningForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
      {financeForm === "contract" && <div className="dialog-backdrop"><form className="dialog surface" onSubmit={createContract}><header><h2>{t("finance.newContract")}</h2><button className="icon-button" type="button" onClick={() => setFinanceForm(null)}><X /></button></header><div className="form-grid"><label className="field form-grid__wide"><span>{t("journal.student")}</span><select required value={contractForm.student} onChange={(event) => setContractForm({ ...contractForm, student: event.target.value })}><option value="" />{students.map((item) => <option key={item.id} value={item.id}>{item.user.display_name} · {item.student_id}</option>)}</select></label><label className="field"><span>{t("finance.contractNumber")}</span><input required value={contractForm.number} onChange={(event) => setContractForm({ ...contractForm, number: event.target.value })} /></label><label className="field"><span>{t("campus.total")}</span><input type="number" min="0" step="0.01" required value={contractForm.total_amount} onChange={(event) => setContractForm({ ...contractForm, total_amount: event.target.value })} /></label><label className="field"><span>{t("finance.currency")}</span><input required maxLength={3} value={contractForm.currency} onChange={(event) => setContractForm({ ...contractForm, currency: event.target.value.toUpperCase() })} /></label><label className="field"><span>{t("finance.signedDate")}</span><input type="date" required value={contractForm.signed_date} onChange={(event) => setContractForm({ ...contractForm, signed_date: event.target.value })} /></label><label className="field"><span>{t("finance.dueDate")}</span><input type="date" value={contractForm.due_date} onChange={(event) => setContractForm({ ...contractForm, due_date: event.target.value })} /></label><label className="field"><span>{t("finance.dueAmount")}</span><input type="number" min="0" step="0.01" value={contractForm.due_amount} onChange={(event) => setContractForm({ ...contractForm, due_amount: event.target.value })} /></label></div><footer><button className="button button--secondary" type="button" onClick={() => setFinanceForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
      {financeForm === "payment" && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={confirmPayment}><header><h2>{t("finance.confirmPayment")}</h2><button className="icon-button" type="button" onClick={() => setFinanceForm(null)}><X /></button></header><label className="field"><span>{t("campus.contracts")}</span><select required value={paymentForm.contract} onChange={(event) => setPaymentForm({ ...paymentForm, contract: event.target.value })}><option value="" />{contracts.map((item) => <option key={item.id} value={item.id}>{item.number} · {item.student_name}</option>)}</select></label><label className="field"><span>{t("finance.paymentDate")}</span><input type="date" required value={paymentForm.payment_date} onChange={(event) => setPaymentForm({ ...paymentForm, payment_date: event.target.value })} /></label><label className="field"><span>{t("finance.amount")}</span><input type="number" min="0.01" step="0.01" required value={paymentForm.amount} onChange={(event) => setPaymentForm({ ...paymentForm, amount: event.target.value })} /></label><label className="field"><span>{t("finance.reference")}</span><input required value={paymentForm.reference} onChange={(event) => setPaymentForm({ ...paymentForm, reference: event.target.value })} /></label><label className="field"><span>{t("exams.comment")}</span><input value={paymentForm.note} onChange={(event) => setPaymentForm({ ...paymentForm, note: event.target.value })} /></label><footer><button className="button button--secondary" type="button" onClick={() => setFinanceForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("finance.confirm")}</button></footer></form></div>}
      {researchForm === "project" && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={createProject}><header><h2>{t("research.newProject")}</h2><button className="icon-button" type="button" onClick={() => setResearchForm(null)}><X /></button></header><label className="field"><span>{t("journal.student")}</span><select required value={projectForm.student} onChange={(event) => setProjectForm({ ...projectForm, student: event.target.value })}><option value="" />{students.map((item) => <option key={item.id} value={item.id}>{item.user.display_name} · {item.student_id}</option>)}</select></label><label className="field"><span>{t("campus.supervisor")}</span><select required value={projectForm.supervisor} onChange={(event) => setProjectForm({ ...projectForm, supervisor: event.target.value })}><option value="" />{teachers.map((item) => <option key={item.id} value={item.id}>{item.user.display_name}</option>)}</select></label><label className="field"><span>{t("research.type")}</span><select value={projectForm.project_type} onChange={(event) => setProjectForm({ ...projectForm, project_type: event.target.value })}><option value="coursework">{t("research.coursework")}</option><option value="thesis">{t("research.thesis")}</option></select></label><label className="field"><span>{t("campus.fieldTitle")}</span><textarea required value={projectForm.title} onChange={(event) => setProjectForm({ ...projectForm, title: event.target.value })} /></label><label className="field"><span>{t("research.defenceDate")}</span><input type="date" value={projectForm.defence_date} onChange={(event) => setProjectForm({ ...projectForm, defence_date: event.target.value })} /></label><footer><button className="button button--secondary" type="button" onClick={() => setResearchForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
      {researchForm === "milestone" && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={createMilestone}><header><h2>{t("research.newMilestone")}</h2><button className="icon-button" type="button" onClick={() => setResearchForm(null)}><X /></button></header><label className="field"><span>{t("research.projects")}</span><select required value={milestoneForm.project} onChange={(event) => setMilestoneForm({ ...milestoneForm, project: event.target.value })}><option value="" />{research.map((item) => <option key={item.id} value={item.id}>{item.student_name} · {item.title}</option>)}</select></label><label className="field"><span>{t("campus.fieldTitle")}</span><input required value={milestoneForm.title} onChange={(event) => setMilestoneForm({ ...milestoneForm, title: event.target.value })} /></label><label className="field"><span>{t("campus.deadline")}</span><input type="date" required value={milestoneForm.due_date} onChange={(event) => setMilestoneForm({ ...milestoneForm, due_date: event.target.value })} /></label><label className="field"><span>{t("exams.comment")}</span><textarea value={milestoneForm.feedback} onChange={(event) => setMilestoneForm({ ...milestoneForm, feedback: event.target.value })} /></label><footer><button className="button button--secondary" type="button" onClick={() => setResearchForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
      {libraryForm === "item" && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={createLibraryItem}><header><h2>{t("library.newItem")}</h2><button className="icon-button" type="button" onClick={() => setLibraryForm(null)}><X /></button></header><label className="field"><span>{t("campus.fieldTitle")}</span><input required value={bookForm.title} onChange={(event) => setBookForm({ ...bookForm, title: event.target.value })} /></label><label className="field"><span>{t("library.authors")}</span><input required value={bookForm.authors} onChange={(event) => setBookForm({ ...bookForm, authors: event.target.value })} /></label><label className="field"><span>ISBN</span><input value={bookForm.isbn} onChange={(event) => setBookForm({ ...bookForm, isbn: event.target.value })} /></label><label className="field"><span>{t("library.year")}</span><input type="number" min="1000" max="2200" value={bookForm.publication_year} onChange={(event) => setBookForm({ ...bookForm, publication_year: event.target.value })} /></label><label className="field"><span>{t("library.copies")}</span><input type="number" min="1" required value={bookForm.total_copies} onChange={(event) => setBookForm({ ...bookForm, total_copies: event.target.value })} /></label><label className="field"><span>{t("campus.resourceUrl")}</span><input type="url" value={bookForm.resource_url} onChange={(event) => setBookForm({ ...bookForm, resource_url: event.target.value })} /></label><footer><button className="button button--secondary" type="button" onClick={() => setLibraryForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
      {libraryForm === "loan" && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={createLibraryLoan}><header><h2>{t("library.newLoan")}</h2><button className="icon-button" type="button" onClick={() => setLibraryForm(null)}><X /></button></header><label className="field"><span>{t("campus.library")}</span><select required value={loanForm.item} onChange={(event) => setLoanForm({ ...loanForm, item: event.target.value })}><option value="" />{books.filter((item) => item.available_copies > 0).map((item) => <option key={item.id} value={item.id}>{item.title} · {item.available_copies}</option>)}</select></label><label className="field"><span>{t("journal.student")}</span><select required value={loanForm.student} onChange={(event) => setLoanForm({ ...loanForm, student: event.target.value })}><option value="" />{students.map((item) => <option key={item.id} value={item.id}>{item.user.display_name} · {item.student_id}</option>)}</select></label><label className="field"><span>{t("library.borrowedAt")}</span><input type="date" required value={loanForm.borrowed_at} onChange={(event) => setLoanForm({ ...loanForm, borrowed_at: event.target.value })} /></label><label className="field"><span>{t("library.dueAt")}</span><input type="date" required value={loanForm.due_at} onChange={(event) => setLoanForm({ ...loanForm, due_at: event.target.value })} /></label><footer><button className="button button--secondary" type="button" onClick={() => setLibraryForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
      {activeQuiz && <div className="dialog-backdrop"><div className="dialog quiz-dialog surface"><header><div><span className="eyebrow">{activeQuiz.subject_name}</span><h2>{activeQuiz.title}</h2></div><button className="icon-button" type="button" onClick={() => setActiveQuiz(null)}><X /></button></header>{quizResult ? <div className="quiz-result"><CheckCircle2 /><strong>{quizResult.correct_count}/{quizResult.total_count}</strong><p>{t("campus.quizCompleted")}</p></div> : <div className="quiz-questions">{activeQuiz.public_questions.map((question, questionIndex) => <fieldset key={questionIndex}><legend>{questionIndex + 1}. {question.prompt}</legend>{question.choices.map((choice, choiceIndex) => <label key={choiceIndex} className={quizAnswers[questionIndex] === choiceIndex ? "is-selected" : ""}><input type="radio" name={`question-${questionIndex}`} checked={quizAnswers[questionIndex] === choiceIndex} onChange={() => setQuizAnswers(quizAnswers.map((answer, index) => index === questionIndex ? choiceIndex : answer))} /><span>{choice}</span></label>)}</fieldset>)}</div>}<footer><button className="button button--secondary" type="button" onClick={() => setActiveQuiz(null)}>{quizResult ? t("campus.close") : t("admissions.cancel")}</button>{!quizResult && <button className="button button--primary" type="button" disabled={busy || quizAnswers.some((answer) => answer < 0)} onClick={() => void submitQuiz()}>{t("campus.finishQuiz")}</button>}</footer></div></div>}
      {operationsForm === "employee" && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={createEmployee}><header><h2>{t("operations.newEmployee")}</h2><button className="icon-button" type="button" onClick={() => setOperationsForm(null)}><X /></button></header><label className="field"><span>{t("operations.employeeId")}</span><input required value={employeeForm.employee_id} onChange={(event) => setEmployeeForm({ ...employeeForm, employee_id: event.target.value })} /></label><label className="field"><span>{t("profile.name")}</span><input required value={employeeForm.full_name} onChange={(event) => setEmployeeForm({ ...employeeForm, full_name: event.target.value })} /></label><label className="field"><span>{t("operations.department")}</span><input required value={employeeForm.department} onChange={(event) => setEmployeeForm({ ...employeeForm, department: event.target.value })} /></label><label className="field"><span>{t("operations.position")}</span><input required value={employeeForm.position} onChange={(event) => setEmployeeForm({ ...employeeForm, position: event.target.value })} /></label><label className="field"><span>{t("operations.hireDate")}</span><input type="date" required value={employeeForm.hire_date} onChange={(event) => setEmployeeForm({ ...employeeForm, hire_date: event.target.value })} /></label><footer><button className="button button--secondary" type="button" onClick={() => setOperationsForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
      {operationsForm === "risk" && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={createRisk}><header><h2>{t("operations.newRisk")}</h2><button className="icon-button" type="button" onClick={() => setOperationsForm(null)}><X /></button></header><label className="field"><span>{t("journal.student")}</span><select required value={riskForm.student} onChange={(event) => setRiskForm({ ...riskForm, student: event.target.value })}><option value="" />{students.map((item) => <option key={item.id} value={item.id}>{item.user.display_name} · {item.student_id}</option>)}</select></label><label className="field"><span>{t("operations.category")}</span><select value={riskForm.category} onChange={(event) => setRiskForm({ ...riskForm, category: event.target.value })}><option value="attendance">{t("operations.attendance")}</option><option value="performance">{t("operations.performance")}</option><option value="finance">{t("campus.finance")}</option></select></label><label className="field"><span>{t("operations.severity")}</span><select value={riskForm.severity} onChange={(event) => setRiskForm({ ...riskForm, severity: event.target.value })}><option value="low">{t("risk.low")}</option><option value="medium">{t("risk.medium")}</option><option value="high">{t("risk.high")}</option></select></label><label className="field"><span>{t("operations.reason")}</span><textarea required value={riskForm.reason} onChange={(event) => setRiskForm({ ...riskForm, reason: event.target.value })} /></label><footer><button className="button button--secondary" type="button" onClick={() => setOperationsForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
      {showMessage && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={sendMessage}><header><h2>{t("communication.compose")}</h2><button className="icon-button" type="button" onClick={() => setShowMessage(false)}><X /></button></header><label className="field"><span>{t("communication.recipient")}</span><select required value={messageForm.recipient} onChange={(event) => setMessageForm({ ...messageForm, recipient: event.target.value })}><option value="" />{recipients.map((item) => <option key={item.id} value={item.id}>{item.name} · {item.detail}</option>)}</select></label><label className="field"><span>{t("communication.subject")}</span><input required value={messageForm.subject} onChange={(event) => setMessageForm({ ...messageForm, subject: event.target.value })} /></label><label className="field"><span>{t("communication.body")}</span><textarea required value={messageForm.body} onChange={(event) => setMessageForm({ ...messageForm, body: event.target.value })} /></label><footer><button className="button button--secondary" type="button" onClick={() => setShowMessage(false)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("communication.send")}</button></footer></form></div>}
      {operationsForm === "document" && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={createHRDocument}><header><h2>{t("operations.newDocument")}</h2><button className="icon-button" type="button" onClick={() => setOperationsForm(null)}><X /></button></header><p className="integration-note">{t("operations.storageRequired")}</p><label className="field"><span>{t("campus.staff")}</span><select required value={documentForm.employee} onChange={(event) => setDocumentForm({ ...documentForm, employee: event.target.value })}><option value="" />{staff.map((item) => <option key={item.id} value={item.id}>{item.full_name} · {item.employee_id}</option>)}</select></label><label className="field"><span>{t("operations.documentType")}</span><input required value={documentForm.document_type} onChange={(event) => setDocumentForm({ ...documentForm, document_type: event.target.value })} /></label><label className="field"><span>{t("campus.fieldTitle")}</span><input required value={documentForm.title} onChange={(event) => setDocumentForm({ ...documentForm, title: event.target.value })} /></label><label className="field"><span>{t("operations.documentNumber")}</span><input value={documentForm.number} onChange={(event) => setDocumentForm({ ...documentForm, number: event.target.value })} /></label><div className="form-grid"><label className="field"><span>{t("operations.issueDate")}</span><input type="date" value={documentForm.issue_date} onChange={(event) => setDocumentForm({ ...documentForm, issue_date: event.target.value })} /></label><label className="field"><span>{t("operations.expiryDate")}</span><input type="date" value={documentForm.expiry_date} onChange={(event) => setDocumentForm({ ...documentForm, expiry_date: event.target.value })} /></label></div><footer><button className="button button--secondary" type="button" onClick={() => setOperationsForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
      {operationsForm === "order" && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={createHROrder}><header><h2>{t("operations.newOrder")}</h2><button className="icon-button" type="button" onClick={() => setOperationsForm(null)}><X /></button></header><label className="field"><span>{t("campus.staff")}</span><select required value={orderForm.employee} onChange={(event) => setOrderForm({ ...orderForm, employee: event.target.value })}><option value="" />{staff.map((item) => <option key={item.id} value={item.id}>{item.full_name} · {item.employee_id}</option>)}</select></label><label className="field"><span>{t("operations.documentNumber")}</span><input required value={orderForm.number} onChange={(event) => setOrderForm({ ...orderForm, number: event.target.value })} /></label><label className="field"><span>{t("operations.orderType")}</span><input required value={orderForm.order_type} onChange={(event) => setOrderForm({ ...orderForm, order_type: event.target.value })} /></label><label className="field"><span>{t("operations.orderDate")}</span><input type="date" required value={orderForm.order_date} onChange={(event) => setOrderForm({ ...orderForm, order_date: event.target.value })} /></label><label className="field"><span>{t("operations.summary")}</span><textarea required value={orderForm.summary} onChange={(event) => setOrderForm({ ...orderForm, summary: event.target.value })} /></label><footer><button className="button button--secondary" type="button" onClick={() => setOperationsForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
      {operationsForm === "note" && selectedRisk && <div className="dialog-backdrop"><form className="dialog dialog--small surface" onSubmit={addRiskNote}><header><div><span className="eyebrow">{selectedRisk.student_name}</span><h2>{t("operations.addNote")}</h2></div><button className="icon-button" type="button" onClick={() => setOperationsForm(null)}><X /></button></header>{selectedRisk.notes?.length > 0 && <div className="risk-note-history">{selectedRisk.notes.map((note) => <article key={note.id}><p>{note.text}</p><small>{note.author_name} · {new Date(note.created_at).toLocaleDateString(language === "tj" ? "tg-TJ" : language)}</small></article>)}</div>}<label className="field"><span>{t("operations.note")}</span><textarea required value={riskNote} onChange={(event) => setRiskNote(event.target.value)} /></label><footer><button className="button button--secondary" type="button" onClick={() => setOperationsForm(null)}>{t("admissions.cancel")}</button><button className="button button--primary" disabled={busy}>{t("journal.save")}</button></footer></form></div>}
    </div>
  );
}
